-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('dc4ef468-c0f2-563c-b2f3-60305f4ea773'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Quel diagramme SysML présente les performances vérifiables attendues ?', 'mcq', '["sd","uc","req","bdd"]'::jsonb, 2, 'Le diagramme d’exigences donne identifiant, texte et critère.', 1),
    ('ecb78916-e1a1-52e3-8398-d6ded6c38f1b'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Que signifie la relation « satisfy » dans un diagramme d’exigences ?', 'mcq', '["Un bloc répond à l’exigence","L’exigence est décomposée","L’exigence est supprimée","Un essai contrôle l’exigence"]'::jsonb, 0, 'Elle relie un constituant à l’exigence qu’il satisfait.', 2),
    ('941ff7eb-a7bb-5d27-9970-9f91e5a704ce'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Quelle relation indique qu’un essai contrôle une exigence ?', 'mcq', '["contains","satisfy","refine","verify"]'::jsonb, 3, 'Un cas de test ou une simulation vérifie l’exigence.', 3),
    ('79c5358b-176f-5b5a-9071-796be7b91af9'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'On vérifie un constituant par rapport…', 'mcq', '["au besoin de l’usager","à sa spécification","au prix de vente","au planning"]'::jsonb, 1, 'On valide le système par rapport au besoin.', 4),
    ('40159861-f133-5f9a-834d-769703fa7b17'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Un chargeur de 150 W de rendement 0,9 fournit à la batterie…', 'mcq', '["135 W","150 W","166 W","90 W"]'::jsonb, 0, '150 × 0,9 = 135 W.', 5),
    ('3ff3f88c-aef3-5f02-8f4f-cf226988e674'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Combien de temps pour charger 500 Wh sous 135 W ?', 'mcq', '["Environ 2,7 h","Environ 3,7 h","Environ 4,6 h","Environ 6,8 h"]'::jsonb, 1, '500 / 135 ≈ 3,7 h.', 6),
    ('dc0a4395-92a4-5a15-a5e1-6d731ec64769'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Avec un chargeur de 120 W (rendement 0,9), l’exigence « moins de 4 h » est-elle satisfaite ?', 'mcq', '["Impossible à dire","Oui, largement","Oui, de justesse","Non : environ 4,6 h"]'::jsonb, 3, '120 × 0,9 = 108 W ; 500 / 108 ≈ 4,6 h.', 7),
    ('f49565eb-1f12-5958-9276-a30e8540f2b8'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Que désigne la qualification d’un système ?', 'mcq', '["La mesure de ses performances réelles une fois produit","Son prix","Son marketing","Son dessin"]'::jsonb, 0, 'C’est la dernière lettre de l’IVVQ.', 8),
    ('5e8a1ce4-7f13-54fa-8dff-e501d0b064f5'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'La réglementation fait partie des parties prenantes à considérer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Normes électriques et accessibilité imposent des exigences.', 9),
    ('fc1ef957-043a-5bcf-a3f6-d7dcabef6453'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Quelle relation relie une exigence technique à l’exigence de haut niveau dont elle découle ?', 'mcq', '["satisfy","allocate","deriveReqt","verify"]'::jsonb, 2, 'Elle « dérive » de l’exigence parente.', 10),
    ('22647b6c-acda-5aec-be56-bd29cd47abb2'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'À l’épreuve, que doit contenir une réponse « justifier que l’exigence est satisfaite » ?', 'mcq', '["Un dessin uniquement","La liste des composants","Une opinion","L’identifiant, une valeur calculée et sa comparaison au critère"]'::jsonb, 3, 'On compare un résultat chiffré au critère de l’exigence.', 11),
    ('1987f5e5-5c4f-59a5-be43-4f1af644f3d4'::uuid, '3aa4439f-3dde-5131-9718-d82bf192cd5e'::uuid, 'Une exigence sans critère chiffré est facilement vérifiable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans critère, on ne peut ni vérifier ni valider.', 12),
    ('afed8b52-262f-5724-9de8-50d56394782e'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Qu’est-ce que l’unité fonctionnelle d’une ACV ?', 'mcq', '["L’unité de masse","Le nombre de pièces","Le service rendu, quantifié, qui sert de base de comparaison","Le prix unitaire"]'::jsonb, 2, 'On compare des services rendus, pas des objets.', 1),
    ('3ad5fc60-8cbd-50b8-afc6-daefe10fce4c'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Combien d’énergie consomme une ampoule de 53 W pendant 10 000 h ?', 'mcq', '["53 kWh","530 kWh","5 300 kWh","5,3 kWh"]'::jsonb, 1, '53 × 10 000 = 530 000 Wh = 530 kWh.', 2),
    ('90fed3e7-95ce-5df2-bf3a-7e0f801915d7'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Avec 60 g de CO2 par kWh, 80 kWh émettent…', 'mcq', '["0,48 kg","4,8 kg","48 kg","480 kg"]'::jsonb, 1, '80 × 60 = 4 800 g = 4,8 kg.', 3),
    ('9e194b66-443b-5ee2-ad0d-c210f0c2db27'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Dans l’exemple, quelle phase domine l’impact des deux ampoules ?', 'mcq', '["Le transport","L’usage","La fin de vie","La fabrication"]'::jsonb, 1, 'L’électricité consommée pèse bien plus que la fabrication.', 4),
    ('b92d1fc6-45fc-5849-8436-eb5412e46cda'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Combien d’halogènes de 2 000 h faut-il pour 10 000 h d’éclairage ?', 'mcq', '["2","5","10","20"]'::jsonb, 1, '10 000 / 2 000 = 5.', 5),
    ('d0ad8705-3402-555b-bb37-4808d8fb2df2'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'En quelle unité exprime-t-on l’impact sur le réchauffement climatique ?', 'mcq', '["kg éq. CO2","m³","kg éq. antimoine","kWh"]'::jsonb, 0, 'Tous les gaz à effet de serre sont convertis en équivalent CO2.', 6),
    ('791e5089-754f-5a8e-8fd5-65b5fac3576a'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Quelle réglementation encadre l’empreinte carbone des bâtiments neufs ?', 'mcq', '["La norme USB","Le Code de la route","La RE2020","Le RGPD"]'::jsonb, 2, 'Elle raisonne sur le cycle de vie du bâtiment.', 7),
    ('a041028f-fed2-5c7c-897d-67c524cc74d0'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Comparer deux produits sans même unité fonctionnelle a du sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut comparer le même service rendu.', 8),
    ('e77beeba-594c-506e-a476-d18135582b47'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Pourquoi remplacer l’acier par de l’aluminium n’est-il pas toujours gagnant ?', 'mcq', '["L’aluminium primaire demande beaucoup d’énergie à produire","L’aluminium ne se recycle pas","L’aluminium rouille","L’aluminium est plus lourd"]'::jsonb, 0, 'Le gain à l’usage doit compenser le surcoût de fabrication.', 9),
    ('6156fff7-c57b-54a8-940a-de2cfa0f27ad'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Quelles normes encadrent l’ACV ?', 'mcq', '["NF C 15-100","IEEE 802.11","ISO 9001","ISO 14040 et 14044"]'::jsonb, 3, 'Ce sont les normes de l’analyse de cycle de vie.', 10),
    ('958e80dc-65fa-5b72-8be2-a1ccc784f9ea'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Un choix d’éco-conception se justifie…', 'mcq', '["par une impression","par un calcul et la phase qu’il améliore","par la couleur du produit","par la mode"]'::jsonb, 1, 'On chiffre l’impact avant et après.', 11),
    ('06ae354f-ea8d-5070-9bad-18f7534af7a0'::uuid, 'ad7bd8d9-b783-5947-92ac-97f8d900f057'::uuid, 'Une commande intelligente peut améliorer l’efficacité globale plus qu’un changement de composant.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'N’utiliser l’énergie que quand c’est utile est un levier puissant.', 12),
    ('0147debb-29e9-528b-b9b0-629a1b7082e5'::uuid, '3d873de7-fd11-5542-b729-2494bf7c30d8'::uuid, 'Quel convertisseur transforme du continu en alternatif ?', 'mcq', '["Le hacheur","L’onduleur","Le gradateur","Le redresseur"]'::jsonb, 1, 'Il alimente par exemple le moteur d’une voiture électrique.', 1),
    ('1bbda091-12d5-5747-b218-7d26cadccc8e'::uuid, '3d873de7-fd11-5542-b729-2494bf7c30d8'::uuid, 'Qu’est-ce que le rapport cyclique α ?', 'mcq', '["La fréquence","La tension maximale","T / t_on","t_on / T"]'::jsonb, 3, 'Il est compris entre 0 et 1.', 2),
    ('2b22809d-6b15-5da6-85a4-6435b75b34a0'::uuid, '3d873de7-fd11-5542-b729-2494bf7c30d8'::uuid, 'Un hacheur alimenté en 24 V avec α = 0,5 fournit en moyenne…', 'mcq', '["6 V","12 V","24 V","48 V"]'::jsonb, 1, 'U moy = α × U alim = 0,5 × 24 = 12 V.', 3),
    ('c537de24-d115-5639-91b9-80b8bf09887a'::uuid, '3d873de7-fd11-5542-b729-2494bf7c30d8'::uuid, 'Quel α faut-il pour obtenir 18 V moyens à partir de 24 V ?', 'mcq', '["0,25","0,50","0,75","1,33"]'::jsonb, 2, '18 / 24 = 0,75.', 4),
    ('90074033-9b6a-563d-9680-f0ef26f6629e'::uuid, '3d873de7-fd11-5542-b729-2494bf7c30d8'::uuid, 'Quelle est la période d’un signal de 20 kHz ?', 'mcq', '["5 µs","20 µs","50 µs","500 µs"]'::jsonb, 2, 'T = 1 / 20 000 = 50 µs.', 5),
    ('0b8a1732-47cd-5dbb-bd0b-018edc3e55ad'::uuid, '3d873de7-fd11-5542-b729-2494bf7c30d8'::uuid, 'Pourquoi un hacheur a-t-il un excellent rendement ?', 'mcq', '["Ses transistors sont soit bloqués, soit saturés","Il n’a pas de composants","Il chauffe beaucoup","Il fonctionne sans courant"]'::jsonb, 0, 'Dans les deux états, le produit U × I dans le transistor est très faible.', 6),
