    ('56067fe4-0d11-5cdf-9231-330fe0049c93'::uuid, 'a5be9b0b-2df9-570c-a9c2-8dfc3b4776c7'::uuid, 'En série, que devient la tension de plusieurs cellules ?', 'mcq', '["Elle s’annule","Elle reste la même","Elle s’additionne","Elle se divise"]'::jsonb, 2, 'La capacité, elle, reste celle d’une cellule.', 4),
