    ('0c3d3738-a4dc-58d5-8f84-e7f4d166fc98'::uuid, '1f54b950-5656-5ba5-a1e5-ca417edba708'::uuid, 'Une gestion intelligente de l’énergie évite surtout de la gaspiller.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle n’en produit pas, elle en économise.', 12),
    ('db86d776-6450-582d-9d37-c0a00ec50833'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'Quels sont les trois choix interdépendants de la conception d’une pièce ?', 'mcq', '["Coût, délai, qualité","Couleur, prix, marque","Forme, matériau, procédé","Moteur, capteur, réseau"]'::jsonb, 2, 'On ne choisit jamais l’un sans les deux autres.', 1),
