    ('d47fced3-4d95-5a91-898c-610fb0313f9a'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'Pourquoi prévoir des dépouilles sur une pièce moulée ?', 'mcq', '["Pour la colorer","Pour l’esthétique","Pour pouvoir la démouler","Pour l’alourdir"]'::jsonb, 2, 'Une légère inclinaison des parois facilite l’extraction.', 3),
