    ('4eed3640-66a0-57de-b4aa-a52ef56a4c35'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'Seuil de rentabilité entre impression 3D (6 €) et injection (25 000 € + 0,80 €) ?', 'mcq', '["Environ 4 800 pièces","Environ 48 000 pièces","Jamais","Environ 480 pièces"]'::jsonb, 0, '25 000 / (6 − 0,8) ≈ 4 808.', 6),
    ('5f1974ee-322b-5340-a000-2796bcb5b961'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'L’usinage est un procédé…', 'mcq', '["de déformation","additif","par enlèvement de matière","de moulage"]'::jsonb, 2, 'Tournage et fraisage enlèvent des copeaux.', 7),
    ('293f1a0c-c1fe-524b-87f9-1725558d5c8d'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'Quel composant réalise un guidage en rotation à faible frottement ?', 'mcq', '["Un roulement à billes","Une crémaillère","Un rivet","Un joint torique"]'::jsonb, 0, 'Les billes roulent au lieu de glisser.', 8),
    ('c79548ce-4000-524a-ba84-a37661e45b5e'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'Pour l’éco-conception, quel assemblage préférer ?', 'mcq', '["Soudure systématique","Surmoulage de métal dans le plastique","Collage de matériaux différents","Assemblage démontable"]'::jsonb, 3, 'Il facilite réparation et tri en fin de vie.', 9),
    ('124be75a-ac58-5e98-8a1d-08b69d878ae6'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'Qu’est-ce que l’optimisation topologique ?', 'mcq', '["Choisir une couleur","Retirer par calcul la matière inutile d’une pièce","Dessiner un plan de ville","Planifier la production"]'::jsonb, 1, 'Elle allège la pièce tout en gardant sa résistance.', 10),
    ('a0ed33f6-ea67-5d72-accd-288b87ea9d55'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'Les nervures rigidifient une pièce plastique sans l’épaissir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles évitent les zones épaisses sources de défauts.', 11),
    ('f86505ca-3538-527b-8b9c-90fbffba8417'::uuid, 'bbe91ce1-b3c8-5000-a0ec-52fac54de825'::uuid, 'La fabrication additive est surtout rentable pour…', 'mcq', '["les très grandes séries","l’unité, les petites séries et les formes complexes","les pièces planes","les tôles"]'::jsonb, 1, 'Elle n’a pas de coût d’outillage, mais un coût par pièce élevé.', 12),
    ('37e19988-8694-5a31-b004-2213a6b739a7'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'Quel composant choisir pour héberger un serveur web avec caméra ?', 'mcq', '["Un capteur de température","Un relais","Un microcontrôleur simple","Un nano-ordinateur"]'::jsonb, 3, 'Il dispose d’un système d’exploitation et de plus de puissance.', 1),
