    ('84ca3467-c704-5566-9a3a-740c4ca931b2'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'Quels langages cite le programme de SIN ?', 'mcq', '["HTML uniquement","Scratch uniquement","Python et C++","Cobol et Fortran"]'::jsonb, 2, 'Ce sont les langages de référence.', 3),
    ('ccfc25dc-0e4a-5a33-b516-690a96399196'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'Dans la serre, que se passe-t-il pour une humidité de 50 % ?', 'mcq', '["Le programme s’arrête","La pompe démarre","La pompe s’arrête","On ne change rien"]'::jsonb, 3, 'Entre 40 et 60 %, l’état de la pompe est conservé : c’est l’hystérésis.', 4),
    ('d2379124-6588-59c5-bb51-2d9aa904e583'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'Pourquoi éviter « attendre 600 s » dans la boucle principale ?', 'mcq', '["Cela coupe le wifi","Cela consomme trop de mémoire","Cela bloquerait la régulation pendant dix minutes","C’est interdit en Python"]'::jsonb, 2, 'On compare plutôt le temps écoulé depuis le dernier envoi.', 5),
    ('89b129bc-6cef-5a30-a93a-a2b4de69e259'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'À quoi sert une interruption ?', 'mcq', '["À arrêter définitivement le programme","À traiter immédiatement un événement urgent","À ralentir la boucle","À compiler le code"]'::jsonb, 1, 'Le programme principal reprend ensuite.', 6),
    ('5e530036-708c-594d-937f-10ae6616a1bc'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'Qu’est-ce qu’un point d’arrêt en débogage ?', 'mcq', '["Un endroit où l’exécution s’interrompt pour inspecter les variables","Une fin de programme","Un bouton d’urgence","Une panne"]'::jsonb, 0, 'On observe l’état du programme à cet instant.', 7),
