    ('fccc349b-99c2-5bfd-a5cd-a451518d2230'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'Quel diagramme décrit les modes Auto, Manuel et Défaut d’un système ?', 'mcq', '["Le diagramme d’états","Le diagramme de blocs","Le diagramme de Sankey","Le diagramme de Gantt"]'::jsonb, 0, 'Chaque mode est un état.', 10),
