    ('22b77641-fae8-5ec3-a070-c8551c1b4ad7'::uuid, 'a00e70c2-52d7-5b2e-84d8-8e3f54ed0458'::uuid, 'Garder les identifiants par défaut d’un objet connecté est sans risque.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils sont connus et exploités par les attaquants.', 12),
