    ('178ef115-fe97-51b0-90cb-9014bb54d76a'::uuid, 'b84660ec-0032-50e1-8ade-b111f3eac345'::uuid, 'Combien de candidats un examinateur évalue-t-il au plus en même temps ?', 'mcq', '["Un","Trois","Dix","Toute la classe"]'::jsonb, 1, 'La note de service fixe ce maximum.', 5),
