    ('28910ec8-28b2-546d-9d6e-f397a8851431'::uuid, 'b84660ec-0032-50e1-8ade-b111f3eac345'::uuid, 'Quelle est la durée indicative du projet de terminale ?', 'mcq', '["36 h","72 h","12 h","150 h"]'::jsonb, 1, 'Il mobilise matière, énergie et information.', 9),
