    ('900a0186-a36b-551b-96ab-03a249b7305f'::uuid, 'b84660ec-0032-50e1-8ade-b111f3eac345'::uuid, 'Un temps de réaction mesuré de 0,08 s pour une exigence de 0,5 s est…', 'mcq', '["impossible","à ignorer","non conforme","conforme"]'::jsonb, 3, '0,08 s < 0,5 s.', 11),
    ('dac483f9-235f-5db3-a12a-8923f8f7a2fc'::uuid, 'b84660ec-0032-50e1-8ade-b111f3eac345'::uuid, 'Le Grand oral peut s’appuyer sur une question issue du projet de 2I2D.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le projet fournit un raisonnement technique concret.', 12),
