    ('d57f0a13-ced1-5585-a6b5-7cfd42b2893a'::uuid, 'bc834f8b-c84a-5de2-b593-88d236291284'::uuid, 'Dans le volet roulant, quel composant adapte l’énergie mécanique ?', 'mcq', '["Le réducteur","Le tablier","Le relais","Le réseau"]'::jsonb, 0, 'Il réduit la vitesse du moteur pour soulever le tablier.', 12),
    ('6515ca57-3a81-52a1-b5bd-974e3ab4bddc'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Combien de degrés de liberté possède un solide libre dans l’espace ?', 'mcq', '["3","4","6","12"]'::jsonb, 2, '3 translations et 3 rotations.', 1),
    ('93a54011-4f9d-5294-ace3-d34e2dd0004a'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Quelle liaison n’autorise qu’une rotation ?', 'mcq', '["Appui plan","Glissière","Pivot","Rotule"]'::jsonb, 2, 'Une charnière de porte est une liaison pivot.', 2),
    ('25e170ec-8b50-520d-8ab2-db8c45f0162c'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Quelle liaison n’autorise qu’une translation ?', 'mcq', '["Glissière","Encastrement","Hélicoïdale","Pivot"]'::jsonb, 0, 'Un tiroir coulisse sans tourner.', 3),
    ('fbd02647-8920-5ccb-baf7-35e9095a2625'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'La liaison vis-écrou est une liaison…', 'mcq', '["appui plan","pivot","rotule","hélicoïdale"]'::jsonb, 3, 'La rotation et la translation y sont liées par le pas.', 4),
    ('20a4e65a-ca18-5510-a10f-4a922c324ec4'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Combien de rotations autorise une rotule ?', 'mcq', '["2","3","Aucune","1"]'::jsonb, 1, 'Elle bloque les trois translations.', 5),
    ('c885d273-6ac0-5e2a-9f4a-a24335fe5c45'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Qu’est-ce qu’une classe d’équivalence cinématique ?', 'mcq', '["Un ensemble de vis","Un groupe de pièces sans mouvement relatif entre elles","Une liste de pièces achetées","Un type de matériau"]'::jsonb, 1, 'Chaque classe est considérée comme un seul solide.', 6),
    ('a328c249-d1cf-51ee-bfeb-1fc57b77b5c6'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Une liaison parfaite néglige…', 'mcq', '["la couleur","les mouvements","la masse","les jeux et les frottements"]'::jsonb, 3, 'C’est l’hypothèse de base du schéma cinématique.', 7),
    ('7828ac60-241e-51f7-8715-f3602de5ba31'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Dans l’étau, quelle liaison relie le corps et le mors mobile ?', 'mcq', '["Glissière","Rotule","Pivot","Hélicoïdale"]'::jsonb, 0, 'Le mors mobile coulisse sans tourner.', 8),
    ('7e84228d-ee23-5efd-b21d-47efe4da4267'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Dans l’étau, quelle liaison relie la vis et le corps ?', 'mcq', '["Encastrement","Appui plan","Pivot","Glissière"]'::jsonb, 2, 'La vis tourne dans le corps sans avancer.', 9),
    ('9c549531-aea6-542d-8e40-f10c64a732d3'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'La tige d’un vérin dans son corps peut tourner et coulisser indépendamment : liaison…', 'mcq', '["encastrement","glissière","pivot","pivot glissant"]'::jsonb, 3, 'Rotation et translation y sont indépendantes.', 10),
    ('3f8e024b-99b8-58b8-9b69-164278e77e83'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Un encastrement autorise un seul mouvement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’en autorise aucun : c’est une liaison complète.', 11),
    ('07e2a384-f860-5473-919f-942e958c6030'::uuid, '8c854966-acad-5c74-b11b-3a7f6ac93170'::uuid, 'Dans un graphe des liaisons, que représente un trait entre deux cercles ?', 'mcq', '["Un flux d’énergie","Une pièce","Une liaison entre deux classes","Un effort"]'::jsonb, 2, 'Chaque cercle est une classe d’équivalence.', 12),
    ('44444200-bcbf-5a82-9a70-32c36ecc77cf'::uuid, '67ac0f15-dc91-5c56-a5b0-53daddd4feeb'::uuid, 'Quelles sont les trois fonctions de la chaîne d’information ?', 'mcq', '["Alimenter, convertir, transmettre","Acquérir, traiter, communiquer","Mesurer, stocker, chauffer","Moduler, adapter, agir"]'::jsonb, 1, 'Elle recueille, décide, puis transmet ordres et messages.', 1),
    ('d3f2285c-08a2-5c95-afd4-d08ec7faaca0'::uuid, '67ac0f15-dc91-5c56-a5b0-53daddd4feeb'::uuid, 'Quel composant réalise la fonction « traiter » ?', 'mcq', '["Un microcontrôleur","Un moteur","Un réducteur","Un capteur"]'::jsonb, 0, 'Il calcule, compare et décide.', 2),
    ('8fc8a9d4-a750-5749-a3c6-04113c60202f'::uuid, '67ac0f15-dc91-5c56-a5b0-53daddd4feeb'::uuid, 'Qu’est-ce que la sensibilité d’un capteur ?', 'mcq', '["Sa taille","Sa plage de mesure","La variation du signal pour une variation de la grandeur","Son prix"]'::jsonb, 2, 'Par exemple 10 mV par degré Celsius.', 3),
    ('3fbfdf69-3873-5ba3-9331-1ca47588dfe0'::uuid, '67ac0f15-dc91-5c56-a5b0-53daddd4feeb'::uuid, 'Un détecteur de présence fournit une information…', 'mcq', '["binaire (tout ou rien)","sonore","mécanique","analogique"]'::jsonb, 0, 'Présent ou absent : deux états seulement.', 4),
    ('3e127def-b972-5c42-ad43-82048839c669'::uuid, '67ac0f15-dc91-5c56-a5b0-53daddd4feeb'::uuid, 'À quoi sert un filtre passe-bas dans une chaîne d’acquisition ?', 'mcq', '["À convertir en numérique","À alimenter le capteur","À amplifier le bruit","À atténuer les variations rapides parasites"]'::jsonb, 3, 'Il garde la mesure lente et enlève le bruit.', 5),
    ('4d4093bb-6050-57a3-b336-d3391a2c58db'::uuid, '67ac0f15-dc91-5c56-a5b0-53daddd4feeb'::uuid, 'Combien de valeurs différentes donne un CAN 10 bits ?', 'mcq', '["10","100","512","1 024"]'::jsonb, 3, '2 puissance 10 = 1 024.', 6),
