    ('80d188d8-072e-5521-a773-08d7c06e6c04'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Que signifie CAO ?', 'mcq', '["Calcul analogique optimisé","Contrôle après opération","Commande automatique d’outils","Conception assistée par ordinateur"]'::jsonb, 3, 'Les logiciels de CAO servent à construire la maquette numérique.', 1),
    ('e2bbc527-10a4-5f57-9c4f-e53bb4dde4ea'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Par quoi commence la modélisation d’une pièce ?', 'mcq', '["Par une esquisse 2D","Par l’assemblage","Par la mise en plan","Par le rendu"]'::jsonb, 0, 'L’esquisse est ensuite transformée en volume.', 2),
    ('8665a490-3f1a-5e43-b4ca-28f98f7cbff0'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Quelle fonction fait tourner une esquisse autour d’un axe ?', 'mcq', '["Extrusion","Chanfrein","Révolution","Répétition"]'::jsonb, 2, 'Elle sert aux pièces cylindriques : axes, poulies, bouteilles.', 3),
