    ('c61cb6da-2455-5ed6-91cd-e7b9a67f17f4'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Que permet l’arbre de construction ?', 'mcq', '["De calculer le prix","De choisir le matériau","De modifier une cote et mettre à jour toute la pièce","D’imprimer la pièce"]'::jsonb, 2, 'C’est le principe de la conception paramétrée.', 5),
    ('0898f895-2139-5d3e-8b5d-674343a7d55b'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'À quoi sert la détection d’interférences dans un assemblage ?', 'mcq', '["À planifier le projet","À repérer deux pièces qui se chevauchent","À calculer la masse","À produire un rendu"]'::jsonb, 1, 'Un chevauchement est une erreur de conception.', 6),
    ('6e6ca129-1ef9-5115-9a5e-fcc8000145cf'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Quelle contrainte d’assemblage aligne deux axes ?', 'mcq', '["La coaxialité","Le congé","L’extrusion","Le contact plan"]'::jsonb, 0, 'Deux axes confondus : un arbre dans un alésage, par exemple.', 7),
