    ('380a7771-729c-5f10-b2d9-fa851d09748f'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Qu’est-ce que la mise en plan ?', 'mcq', '["Une simulation de chute","Un planning","Un dessin 2D coté destiné à la fabrication","Une vue 3D colorée"]'::jsonb, 2, 'Elle est tirée automatiquement de la maquette.', 9),
    ('975f162f-8fdc-56c0-b4c1-87d100d02672'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Dans l’exemple, pourquoi porter l’encoche à 10 mm pour un téléphone de 9 mm ?', 'mcq', '["Pour laisser un jeu permettant l’insertion","Pour l’esthétique","Parce que 10 est un nombre rond","Pour gagner de la matière"]'::jsonb, 0, 'Une encoche exactement à la cote serait trop serrée.', 10),
    ('0c29f576-4ab8-5f74-b8bb-09f29e8d57c4'::uuid, 'a54a7159-d739-5be1-acee-63279adbbe89'::uuid, 'Qu’est-ce qui distingue un jumeau numérique d’une simple maquette ?', 'mcq', '["Il n’a pas de volume","Il remplace le produit réel","Il est en papier","Il est dynamique et reproduit le comportement du produit réel"]'::jsonb, 3, 'Il peut être alimenté par les données des capteurs du produit.', 11),
