    ('f3c08bed-0490-5ea9-8d6d-2f43767de0cd'::uuid, '9451773a-4295-5b11-b025-0f6dd2714833'::uuid, 'Quel format de fichier exporte-t-on pour l’impression 3D ?', 'mcq', '["STL","MP3","PDF","TXT"]'::jsonb, 0, 'Le format STL décrit la surface par des triangles.', 3),
    ('e72bae28-d33f-5b0a-80ef-33bd9bf7a2d5'::uuid, '9451773a-4295-5b11-b025-0f6dd2714833'::uuid, 'Que fait le logiciel de tranchage ?', 'mcq', '["Il calcule le prix de vente","Il dessine la pièce","Il découpe la pièce en couches et génère le parcours de la buse","Il peint la pièce"]'::jsonb, 2, 'Il produit le G-code lu par l’imprimante.', 4),
