    ('d1e78799-2bbd-5ec4-a575-7231dab71eab'::uuid, '9451773a-4295-5b11-b025-0f6dd2714833'::uuid, 'Une maquette d’aspect sert surtout à vérifier…', 'mcq', '["le rendement","les performances électriques","les formes, proportions et prise en main","la résistance mécanique"]'::jsonb, 2, 'Elle ne fonctionne pas forcément.', 6),
    ('f7dc2dae-68ea-5606-8676-13f3055df24b'::uuid, '9451773a-4295-5b11-b025-0f6dd2714833'::uuid, 'Le fraisage à commande numérique est un procédé soustractif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un outil rotatif enlève de la matière au brut.', 7),
