    ('b209c0b4-aa62-5173-a72e-3da5193f9be3'::uuid, '9451773a-4295-5b11-b025-0f6dd2714833'::uuid, 'Quelle est la masse d’une pièce pleine de 30 cm³ en PLA (1,24 g/cm³) ?', 'mcq', '["24 g","30 g","37 g environ","124 g"]'::jsonb, 2, '30 × 1,24 = 37,2 g.', 9),
