    ('bd5d8321-cf32-5707-9a07-73306e9e3c06'::uuid, '9451773a-4295-5b11-b025-0f6dd2714833'::uuid, 'Quel procédé permet de reproduire une pièce imprimée en petite série ?', 'mcq', '["La mise en plan","La découpe laser","Le coulage en résine dans un moule silicone","Le tranchage"]'::jsonb, 2, 'Le moule silicone est pris sur la pièce imprimée.', 11),
    ('04718153-1fed-5e4e-bc42-2e484e02f822'::uuid, '9451773a-4295-5b11-b025-0f6dd2714833'::uuid, 'Un prototype n’a de valeur que par les essais qu’on lui fait subir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Fabriquer sans tester ne valide rien.', 12),
    ('6313713c-62da-5608-82df-77fe083df252'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'Quelle est la durée indicative du projet de fin de première ?', 'mcq', '["Environ 36 heures","72 heures","100 heures","6 heures"]'::jsonb, 0, 'Le projet de terminale, lui, dure 72 heures.', 1),
    ('d5e633f5-5126-5cfa-96f5-67f8f9e17859'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'Comment l’innovation technologique est-elle évaluée au baccalauréat ?', 'mcq', '["Par le grand oral uniquement","Elle n’est pas évaluée","Par une épreuve écrite de 4 h","En contrôle continu"]'::jsonb, 3, 'La spécialité s’arrête en fin de première.', 2),
    ('6504b39b-59cb-5042-8f49-376f4f801b05'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'Quel est son coefficient au baccalauréat ?', 'mcq', '["2","5","8","16"]'::jsonb, 2, 'Comme toute spécialité abandonnée en fin de première.', 3),
    ('f5354232-6d51-5194-b413-a39198ab4720'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'Que devient l’innovation technologique en terminale ?', 'mcq', '["Elle disparaît sans suite","Elle fusionne avec I2D dans la spécialité 2I2D","Elle devient une option facultative","Elle est remplacée par la physique"]'::jsonb, 1, 'I2D et IT forment en terminale « ingénierie, innovation et développement durable ».', 4),
    ('6b01a6b5-8620-5d91-8d9b-29c77fbb889a'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'À quoi sert le carnet de bord ?', 'mcq', '["À noter les absences","À garder la trace de ce qui a été fait et des décisions","À remplacer le prototype","À calculer la note"]'::jsonb, 1, 'Il montre la démarche au jury.', 5),
    ('4bf84d5d-4833-56ad-bdd2-bc27da4f0ed2'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'Que doit préciser une bonne problématique ?', 'mcq', '["Le prix du prototype","Le nom du logiciel","La solution retenue","L’utilisateur et le besoin, en laissant les solutions ouvertes"]'::jsonb, 3, 'Imposer une solution dès la question fermerait la recherche.', 6),
    ('71d0b785-c0be-5eae-a648-7db91ff1956c'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'Pendant l’oral, que faire de ce qui ne fonctionne pas ?', 'mcq', '["L’analyser et proposer une amélioration","Accuser un camarade","N’en rien dire","Le cacher"]'::jsonb, 0, 'Analyser un écart est une compétence évaluée.', 7),
    ('0ac913be-57ea-50b4-b62f-f9150f199869'::uuid, '4df3b487-c235-53a8-a75d-9b5b9a82c0ae'::uuid, 'Le jury évalue uniquement la qualité de l’objet final.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il évalue surtout la démarche et la justification des choix.', 8),
