    ('ac3be37c-1748-503e-8dc3-9c3c55988629'::uuid, '9041316e-60b9-579f-8758-97ed41a6b05d'::uuid, 'Des mesures très groupées mais loin de la vraie valeur sont…', 'mcq', '["justes et fidèles","fidèles mais pas justes","justes mais pas fidèles","ni justes ni fidèles"]'::jsonb, 1, 'La dispersion est faible, mais la moyenne est décalée.', 3),
    ('7fabe427-668f-5ae9-a28e-4653d89f2c1d'::uuid, '9041316e-60b9-579f-8758-97ed41a6b05d'::uuid, 'Moyenne de 1,42 ; 1,45 ; 1,40 ; 1,44 ; 1,44 s ?', 'mcq', '["1,41 s","1,43 s","1,44 s","1,45 s"]'::jsonb, 1, '7,15 / 5 = 1,43 s.', 4),
